/* Wissen › Wiederholung › Techniken: Lernpfad Studien verstehen. Stand 21.11.2026, Quellen je Einheit. Entwurf, fachlich prüfen. */
WDH_woche({"kw": "studien", "pfad": true, "titel": "Studien verstehen", "unter": "Studientypen, Statistik, Studien lesen und bewerten · Entwurf, fachlich prüfen", "bloecke": {"A": "Grundlagen", "B": "Zahlen verstehen", "C": "Lesen und bewerten", "D": "Prüfung"}, "techniken": [{"id": "stud-typen", "titel": "Studientypen, Evidenz und Leitlinien", "art": "grund", "block": "A", "min": 12, "bild": "fortbildung/bilder/studien/stud-pyramide.webp", "abschnitte": [{"t": "1. Warum dich das betrifft", "b": [{"p": ["Fast jede Fortbildung, jedes Gerät und jede neue Methode wirbt mit „Studien belegen …“. Patienten bringen Artikel mit, Ärzte verordnen nach Leitlinie, und in der Befundung entscheidest du jeden Tag, welchem Test du traust. Wer Studien lesen kann, fällt auf weniger Werbung herein und kann begründen, warum er etwas macht.", "[[Evidenzbasierte Praxis|ebm]] heißt dabei nicht „nur was im RCT steht“. Sie verbindet drei Dinge: die beste verfügbare Forschung, deine klinische Erfahrung und das, was der Patient will und mitbringt."]}, {"merk": "Evidenz ist ein Baustein der Entscheidung, nicht die ganze Entscheidung. Aber ohne sie entscheidest du nach Gefühl."}]}, {"t": "2. Die Frage bestimmt das Studiendesign", "b": [{"p": ["Es gibt nicht „die beste Studie“, sondern das passende Design für eine bestimmte Frage. Ein RCT taugt nichts, wenn du wissen willst, wie häufig eine Erkrankung ist."]}, {"tab": [["Hilft die Behandlung?", "Randomisierte kontrollierte Studie (RCT), Zusammenfassung in systematischen Reviews"], ["Taugt der Test?", "Diagnostische Genauigkeitsstudie: alle Patienten bekommen Test und Referenzstandard"], ["Wie geht es weiter (Prognose)?", "Kohortenstudie, Patienten werden über die Zeit begleitet"], ["Was erhöht das Risiko?", "Kohorte, bei seltenen Erkrankungen Fall-Kontroll-Studie"], ["Wie häufig ist es?", "Querschnittsstudie"], ["Wie erleben Patienten es?", "Qualitative Studie (Interviews, Fokusgruppen)"]]}, {"merk": "Erst die Frage klären, dann schauen, ob das Design dazu passt."}]}, {"t": "3. Beobachten: Kohorte, Fall-Kontrolle, Querschnitt", "b": [{"p": ["In Beobachtungsstudien greift niemand ein. Man schaut nur zu, wer was macht und was passiert. Das ist oft die einzige Möglichkeit, etwa bei Risikofaktoren, die man niemandem zuteilen darf.", "Das große Problem sind [[Störfaktoren|confounder]]. Beispiel: Patienten, die ihre Heimübungen fleißig machen, haben am Ende weniger Schmerz. Das kann an den Übungen liegen. Es kann aber auch sein, dass gerade die Patienten mit weniger Schmerz und mehr Zuversicht überhaupt üben."]}, {"tab": [["Kohorte", "Gruppe wird über Zeit begleitet. Gut für Prognose und Risikofaktoren. Prospektiv besser als retrospektiv."], ["Fall-Kontrolle", "Erkrankte werden mit Gesunden verglichen, man schaut zurück. Schnell, aber anfällig für Erinnerungsfehler."], ["Querschnitt", "Ein Zeitpunkt, eine Momentaufnahme. Zeigt Häufigkeit, aber keine Reihenfolge von Ursache und Wirkung."], ["Fallserie, Fallbericht", "Einzelne Patienten beschrieben. Liefert Ideen, keinen Beleg."]]}, {"merk": "Korrelation ist keine Kausalität. Ein Zusammenhang in Beobachtungsdaten zeigt nur, dass zwei Dinge gemeinsam auftreten."}]}, {"t": "4. Eingreifen: die randomisierte kontrollierte Studie", "b": [{"p": ["Im RCT entscheidet der Zufall, wer welche Behandlung bekommt. Dadurch verteilen sich auch unbekannte Störfaktoren gleichmäßig auf die Gruppen. Unterscheiden sich die Gruppen am Ende, liegt das mit hoher Wahrscheinlichkeit an der Behandlung.", "Damit das klappt, muss die Zuteilung vorher [[verdeckt|concealment]] bleiben. Wer Patienten aufnimmt, darf nicht wissen, in welche Gruppe der Nächste kommt."]}, {"l": ["Kontrollgruppe: Placebo oder Sham, übliche Versorgung, eine andere Therapie oder eine Warteliste. Gegen Warteliste sieht fast alles gut aus.", "Verblindung: Patient, Therapeut und Untersucher wissen nicht, wer was bekommt. In der Physiotherapie lässt sich der Therapeut kaum verblinden, der Untersucher fast immer.", "Varianten: Cross-over (jeder bekommt beides nacheinander), Cluster (ganze Praxen werden zugeteilt), Pilotstudie (prüft, ob ein großer RCT machbar ist).", "Nichtunterlegenheitsstudie: zeigt, dass eine einfachere oder günstigere Behandlung nicht schlechter ist als der Standard."]}, {"merk": "Randomisierung schützt vor Störfaktoren, Verblindung vor Erwartung. Beides zusammen macht den RCT stark."}]}, {"t": "5. Zusammenfassen: Reviews und Metaanalysen", "b": [{"p": ["Eine einzelne Studie kann Glück oder Pech haben. Deshalb fasst man Studien zusammen. Ein systematischer Review sucht nach einem vorher festgelegten Plan alle Studien zu einer Frage, bewertet sie und fasst sie zusammen. Werden die Zahlen dabei rechnerisch gepoolt, ist es eine Metaanalyse.", "Davon zu unterscheiden ist die narrative Übersichtsarbeit. Dort wählen die Autoren selbst aus, was sie zitieren. Das ist lesenswert, aber anfällig für Lieblingsstudien."]}, {"tab": [["Systematischer Review", "Festes Protokoll, vollständige Suche, Qualitätsbewertung. Berichtet nach PRISMA 2020."], ["Metaanalyse", "Rechnet die Ergebnisse zusammen, meist als Forest Plot."], ["Cochrane-Review", "Systematischer Review nach strengen Cochrane-Regeln, mit GRADE-Bewertung."], ["Netzwerk-Metaanalyse", "Vergleicht mehrere Therapien gleichzeitig, auch solche, die nie direkt gegeneinander getestet wurden."], ["Umbrella-Review", "Fasst mehrere Reviews zusammen."]]}, {"merk": "Eine Metaanalyse aus schlechten Studien bleibt schlecht. Zusammenrechnen macht nichts besser, es macht es nur genauer falsch."}]}, {"t": "6. Die Evidenzpyramide und ihre Grenzen", "b": [{"p": ["Die bekannte Pyramide ordnet Studientypen nach ihrer Anfälligkeit für Verzerrung. Für Therapiefragen sieht das etwa so aus (angelehnt an die [[Oxford-Level|ocebm]]):"]}, {"tab": [["Oben", "Systematischer Review aus RCTs"], ["Darunter", "Einzelner guter RCT"], ["Mitte", "Kohortenstudie, nicht randomisierte kontrollierte Studie"], ["Unten", "Fall-Kontroll-Studie, Fallserie"], ["Ganz unten", "Expertenmeinung, Mechanismus-Überlegung („das muss ja wirken, weil …“)"]]}, {"p": ["Die Pyramide ist eine Faustregel. Eine sauber gemachte Kohortenstudie mit tausenden Patienten kann mehr wert sein als ein kleiner, schlampiger RCT. Moderne Systeme wie [[GRADE|grade]] bewerten deshalb nicht nur das Design, sondern auch Durchführung, Präzision und Übereinstimmung der Studien."]}, {"merk": "Das Design gibt den Startpunkt vor. Wie gut eine Studie wirklich ist, entscheidet ihre Durchführung."}]}, {"t": "7. Leitlinien richtig einordnen", "b": [{"p": ["Leitlinien übersetzen die Studienlage in Empfehlungen. In Deutschland stehen sie im [[AWMF-Register|awmf]] und haben eine Stufe:"]}, {"tab": [["S1", "Expertengruppe, informeller Konsens. Keine systematische Literatursuche."], ["S2k", "Strukturierter Konsens eines repräsentativen Gremiums."], ["S2e", "Systematische Recherche und Bewertung der Literatur, ohne formalen Konsens."], ["S3", "Beides: systematische Evidenz und strukturierter Konsens. Höchste Stufe."]]}, {"p": ["Die Stärke einer Empfehlung erkennst du an der Sprache: „soll“ (Grad A, stark), „sollte“ (Grad B) und „kann“ (Grad 0, offen). Negativ: „soll nicht“. Schau immer auf das Datum. Jede AWMF-Leitlinie hat eine Gültigkeit, danach gilt sie als abgelaufen, bis sie überarbeitet ist."]}, {"l": ["Leitlinien sind Handlungskorridore, kein Gesetz. Begründete Abweichung im Einzelfall ist erlaubt und gehört dokumentiert.", "Eine starke Empfehlung kann auf schwacher Evidenz beruhen, wenn Nutzen und Risiko klar sind. Deshalb steht meist beides dabei: Empfehlungsgrad und Evidenzgrad.", "Internationale Leitlinien für Physiotherapie: JOSPT/APTA (USA), KNGF (Niederlande), NICE (England)."]}, {"merk": "S1 ist Meinung mit Briefkopf, S3 ist der Goldstandard. Und immer das „gültig bis“ prüfen."}]}], "info": {"ebm": {"t": "Evidenzbasierte Praxis", "x": ["Nach Sackett 1996 der gewissenhafte und vernünftige Gebrauch der besten aktuellen Evidenz für Entscheidungen beim einzelnen Patienten.", "Drei Säulen: Forschung, klinische Expertise, Werte und Wünsche des Patienten. Keine Säule ersetzt die anderen."], "q": "Sackett DL et al. BMJ 1996"}, "confounder": {"t": "Confounder (Störfaktor)", "x": ["Ein dritter Faktor, der sowohl mit der vermuteten Ursache als auch mit dem Ergebnis zusammenhängt und so einen falschen Zusammenhang vortäuscht.", "Klassisches Beispiel: Kaffeetrinker bekommen öfter Lungenkrebs. Der Confounder ist das Rauchen. Statistisch kann man bekannte Confounder herausrechnen, unbekannte nur durch Randomisierung ausgleichen."]}, "concealment": {"t": "Verdeckte Zuteilung (Allocation Concealment)", "x": ["Die Zuteilungsliste ist für die Person, die Patienten aufnimmt, nicht einsehbar, zum Beispiel über zentrale Randomisierung per Telefon oder versiegelte, undurchsichtige Umschläge.", "Fehlt das, kann man unbewusst die „besseren“ Patienten in die Therapiegruppe lenken. Das ist ein eigener Punkt in PEDro und RoB 2."]}, "ocebm": {"t": "Oxford-Evidenzlevel", "x": ["Das Oxford Centre for Evidence-Based Medicine hat 2011 Level von 1 bis 5 festgelegt, getrennt nach Frageart (Therapie, Diagnostik, Prognose, Häufigkeit).", "Für Therapie: Level 1 systematischer Review aus RCTs, Level 2 einzelner RCT, Level 3 Kohorte, Level 4 Fallserie oder Fall-Kontrolle, Level 5 Mechanismus-Überlegung."], "q": "OCEBM Levels of Evidence Working Group 2011"}, "grade": {"t": "GRADE", "x": ["Grading of Recommendations Assessment, Development and Evaluation. Bewertet die Vertrauenswürdigkeit eines ganzen Studienbefunds in vier Stufen: hoch, moderat, niedrig, sehr niedrig.", "Wird von Cochrane, WHO und vielen Leitlinien genutzt. Mehr dazu in der Einheit „Gut oder schlecht?“."], "q": "Cochrane Handbook, Kap. 14"}, "awmf": {"t": "AWMF-Leitlinienregister", "x": ["Die Arbeitsgemeinschaft der Wissenschaftlichen Medizinischen Fachgesellschaften sammelt alle deutschen Leitlinien kostenlos unter register.awmf.org.", "Dort stehen Stufe, beteiligte Fachgesellschaften, Stand und „gültig bis“. Nationale Versorgungsleitlinien (NVL, etwa Kreuzschmerz) laufen über ÄZQ und AWMF."], "q": "AWMF-Regelwerk Leitlinien"}}, "quellen": ["Sackett DL et al. Evidence based medicine: what it is and what it isn't. BMJ 1996", "OCEBM Levels of Evidence Working Group. The Oxford 2011 Levels of Evidence", "Page MJ et al. PRISMA 2020 statement. BMJ 2021", "Higgins JPT et al. Cochrane Handbook for Systematic Reviews of Interventions, Version 6", "AWMF-Regelwerk Leitlinien: Stufenklassifikation S1, S2k, S2e, S3", "Kopp IB, Rahn K. Leitlinien in der klinischen Praxis. Bundesgesundheitsbl 2015"], "fragen": [["Du willst wissen, ob eine neue Übungstherapie Knieschmerz senkt. Welches Design passt am besten?", ["Randomisierte kontrollierte Studie", "Querschnittsstudie", "Fallbericht", "Qualitative Studie"], 0, "Für die Frage „Hilft die Behandlung?“ ist der RCT das passende Design, zusammengefasst im systematischen Review."], ["Was ist der Hauptvorteil der Randomisierung?", ["Die Studie wird billiger", "Auch unbekannte Störfaktoren verteilen sich gleichmäßig", "Die Patienten wissen nicht, was sie bekommen", "Es braucht weniger Teilnehmer"], 1, "Der Zufall verteilt bekannte und unbekannte Störfaktoren gleich. Das Nichtwissen ist Verblindung, etwas anderes."], ["Patienten, die viel üben, haben weniger Schmerz. Warum beweist das noch nicht, dass Üben hilft?", ["Weil Confounder wie Motivation oder Ausgangsschmerz dahinterstecken können", "Weil Schmerz nicht messbar ist", "Weil Üben nie hilft", "Weil die Zahl zu klein ist"], 0, "Beobachtete Zusammenhänge können durch Störfaktoren entstehen. Erst ein Vergleich mit zufälliger Zuteilung zeigt Ursache und Wirkung."], ["Was bedeutet verdeckte Zuteilung (Allocation Concealment)?", ["Der Patient weiß nicht, welche Therapie er bekommt", "Wer Patienten aufnimmt, kennt die nächste Gruppenzuteilung nicht", "Der Untersucher ist verblindet", "Die Daten werden anonymisiert"], 1, "Concealment schützt die Zuteilung vor Manipulation, bevor der Patient in der Studie ist. Verblindung kommt danach."], ["Wer lässt sich in Physiotherapie-RCTs fast immer verblinden?", ["Der behandelnde Therapeut", "Der Patient bei Übungstherapie", "Niemand", "Der Untersucher, der die Ergebnisse misst"], 3, "Den Therapeuten kann man kaum verblinden. Der Untersucher, der misst, kann fast immer im Unklaren bleiben."], ["Was unterscheidet einen systematischen Review von einer narrativen Übersicht?", ["Er ist kürzer", "Festes Protokoll, vollständige Suche und Qualitätsbewertung", "Er enthält immer eine Metaanalyse", "Er stammt immer von Cochrane"], 1, "Systematisch heißt: vorher festgelegter Plan und vollständige Suche. Eine Metaanalyse ist möglich, aber nicht Pflicht."], ["Was gilt für eine Metaanalyse aus methodisch schwachen Studien?", ["Sie wird durch das Zusammenrechnen verlässlich", "Sie ist automatisch Level 1", "Sie darf nicht veröffentlicht werden", "Sie bleibt schwach, wird nur genauer"], 3, "Zusammenrechnen verkleinert den Zufallsfehler, nicht die Verzerrung. Garbage in, garbage out."], ["Für welche Frage ist eine Querschnittsstudie geeignet?", ["Wirkt eine Therapie?", "Wie ist die Langzeitprognose?", "Ist ein Test besser als ein anderer?", "Wie häufig ist eine Erkrankung?"], 3, "Der Querschnitt ist eine Momentaufnahme und zeigt Häufigkeiten. Für Ursache und Wirkung fehlt die zeitliche Reihenfolge."], ["Welche AWMF-Stufe verbindet systematische Evidenzrecherche und strukturierten Konsens?", ["S1", "S2k", "S2e", "S3"], 3, "S3 hat beides. S2e nur die Evidenz, S2k nur den Konsens, S1 keins von beiden formal."], ["Eine Leitlinie schreibt „sollte angewendet werden“. Welcher Empfehlungsgrad ist das?", ["A, starke Empfehlung", "0, offene Empfehlung", "B, Empfehlung", "Expertenkonsens ohne Grad"], 2, "Soll = A, sollte = B, kann = 0."], ["Wo steht im Oxford-System von 2011 die Mechanismus-Überlegung („muss ja wirken, weil …“)?", ["Level 1", "Level 2", "Level 3", "Level 5"], 3, "Level 5, ganz unten. Plausibel klingende Mechanismen sind kein Wirkungsnachweis."], ["Was musst du bei jeder AWMF-Leitlinie zuerst prüfen?", ["Die Seitenzahl", "Die Gültigkeit (gültig bis)", "Ob ein Physiotherapeut mitgeschrieben hat", "Ob sie auf Englisch vorliegt"], 1, "Abgelaufene Leitlinien können überholt sein. Das Datum steht im Register."]]}, {"id": "stud-zahlen", "titel": "Zahlen in Studien: Signifikanz, Konfidenzintervall, Effekt", "art": "grund", "block": "B", "min": 14, "bild": "fortbildung/bilder/studien/stud-tablet.webp", "abschnitte": [{"t": "1. Mittelwert, Streuung und Verteilung", "b": [{"p": ["Fast jede Studie beschreibt ihre Gruppen erst einmal mit einem Lagemaß und einem Streuungsmaß. Der Mittelwert ist der Durchschnitt. Der Median ist der Wert in der Mitte, wenn man alle der Größe nach ordnet. Bei schiefen Daten (zum Beispiel Krankheitsdauer, wo einige wenige sehr lange krank sind) ist der Median ehrlicher.", "Die Standardabweichung (SD) zeigt, wie stark die einzelnen Patienten um den Mittelwert streuen. Bei normalverteilten Daten liegen etwa zwei Drittel der Werte innerhalb von einer SD um den Mittelwert, etwa 95 % innerhalb von zwei SD."]}, {"tab": [["SD (Standardabweichung)", "Streuung der einzelnen Patienten"], ["SE (Standardfehler)", "Unsicherheit des Mittelwerts, wird mit wachsender Teilnehmerzahl kleiner"], ["IQR (Interquartilsabstand)", "Bereich der mittleren 50 %, gehört zum Median"]]}, {"merk": "Wer statt der SD den viel kleineren SE zeigt, lässt Daten einheitlicher aussehen, als sie sind. Schau, was in der Tabelle steht."}]}, {"t": "2. Der p-Wert, und was er nicht ist", "b": [{"p": ["Statistische Tests starten mit der Nullhypothese: Es gibt keinen Unterschied zwischen den Gruppen. Der p-Wert gibt an, wie wahrscheinlich ein Ergebnis wie dieses (oder ein noch extremeres) wäre, wenn die Nullhypothese stimmt. Ist p kleiner als 0,05, nennt man das Ergebnis „statistisch signifikant“.", "Die Grenze 0,05 ist eine Konvention, kein Naturgesetz. Die [[American Statistical Association|asa]] hat 2016 klargestellt, was der p-Wert alles nicht kann."]}, {"l": ["Er ist nicht die Wahrscheinlichkeit, dass die Hypothese stimmt.", "Er sagt nichts über die Größe oder Wichtigkeit eines Effekts.", "p = 0,049 und p = 0,051 sind praktisch dasselbe Ergebnis.", "„Nicht signifikant“ heißt nicht „kein Effekt“. Oft war die Studie einfach zu klein."]}, {"p": ["Dazu gehören zwei mögliche Fehler. [[Fehler 1. Art|alphabeta]]: Man findet einen Effekt, der in Wahrheit nicht existiert. Fehler 2. Art: Man übersieht einen Effekt, der existiert. Wie gut eine Studie Effekte findet, heißt Power. Üblich sind 80 %, geplant über eine Fallzahlberechnung vor Studienbeginn."]}, {"merk": "Signifikant heißt nur „wahrscheinlich nicht reiner Zufall“. Ob der Effekt groß genug ist, sagt der p-Wert nicht."}]}, {"t": "3. Das Konfidenzintervall", "b": [{"p": ["Viel aussagekräftiger als der p-Wert ist das 95-%-Konfidenzintervall (KI). Es gibt einen Bereich an, in dem der wahre Effekt mit hoher Wahrscheinlichkeit liegt. Schmal heißt präzise, breit heißt unsicher.", "Beispiel: Übungsgruppe gegen Kontrolle, Unterschied beim Schmerz −1,2 Punkte auf der NRS (95-%-KI −2,1 bis −0,3). Der beste Schätzwert ist −1,2. Der wahre Effekt kann aber auch nur −0,3 sein, also kaum spürbar, oder −2,1, also deutlich."]}, {"tab": [["Unterschiede (Differenz)", "Die Nulllinie liegt bei 0. Schließt das KI die 0 ein, ist das Ergebnis nicht signifikant."], ["Verhältnisse (RR, OR)", "Die Nulllinie liegt bei 1. Schließt das KI die 1 ein, ist das Ergebnis nicht signifikant."]]}, {"p": ["Am meisten bringt das KI, wenn du es neben die kleinste spürbare Veränderung hältst (Abschnitt 5). Liegt das ganze KI jenseits dieser Grenze, ist der Effekt sicher relevant. Reicht es von „bedeutungslos“ bis „groß“, weiß man es einfach noch nicht."]}, {"merk": "Lies immer zuerst das Konfidenzintervall. Es zeigt Richtung, Größe und Unsicherheit auf einen Blick."}]}, {"t": "4. Effektgrößen: wie viel bringt es?", "b": [{"tab": [["Mittlere Differenz (MD)", "Unterschied in der Originaleinheit, z. B. −1,2 Punkte NRS oder +12° Flexion. Am leichtesten zu verstehen."], ["Standardisierte MD (SMD)", "Unterschied geteilt durch die Streuung, nötig wenn Studien verschiedene Skalen nutzen. Grobe Faustregel nach [[Cohen|cohen]]: 0,2 klein, 0,5 mittel, 0,8 groß."], ["Relatives Risiko (RR), Odds Ratio (OR)", "Verhältnis zweier Risiken bzw. Chancen. RR 0,5 heißt: halb so häufig."], ["Absolute Risikoreduktion (ARR)", "Unterschied der Ereignisraten in Prozentpunkten."], ["Number needed to treat (NNT)", "Wie viele Patienten man behandeln muss, damit einer zusätzlich profitiert. NNT = 1 / ARR."]]}, {"p": ["Ein Rechenbeispiel zeigt, warum die Art der Zahl so wichtig ist. Ohne Programm erleiden 20 von 100 Läufern eine Verletzung, mit Präventionsprogramm 10 von 100."]}, {"bars": [["Relative Risikoreduktion", 50, "50 %: klingt riesig"], ["Absolute Risikoreduktion", 10, "10 Prozentpunkte"], ["Ereignisrate ohne Programm", 20, "20 von 100"], ["Ereignisrate mit Programm", 10, "10 von 100"]]}, {"p": ["Die NNT ist hier 1 / 0,10 = 10. Zehn Läufer müssen das Programm machen, damit eine Verletzung weniger auftritt. Wäre die Ausgangsrate nur 2 von 100 und sänke auf 1 von 100, bliebe die relative Reduktion bei 50 %, die NNT wäre aber 100."]}, {"merk": "Relative Zahlen klingen immer größer. Frag nach dem absoluten Unterschied oder der NNT."}]}, {"t": "5. Klinische Relevanz: MCID und MDC", "b": [{"p": ["Ein Unterschied kann statistisch signifikant und trotzdem für den Patienten bedeutungslos sein. Große Studien mit tausenden Teilnehmern machen schon winzige Unterschiede signifikant. Umgekehrt kann eine kleine Studie einen relevanten Effekt nicht absichern.", "Deshalb gibt es die [[MCID|mcid]], die kleinste Veränderung, die Patienten als bedeutsam wahrnehmen. Beim Schmerz auf der 0-bis-10-Skala liegt sie nach [[Farrar|farrar]] bei etwa 2 Punkten oder 30 %.", "Davon getrennt ist der [[MDC|mdc]], die kleinste Veränderung, die über dem Messfehler liegt. Ist die MCID kleiner als der MDC, kannst du einen bedeutsamen Fortschritt beim einzelnen Patienten gar nicht sicher messen."]}, {"tab": [["Signifikant und relevant", "KI liegt komplett jenseits der MCID. Gut belegt."], ["Signifikant, aber nicht relevant", "KI schließt 0 aus, bleibt aber unter der MCID. Typisch für sehr große Studien."], ["Nicht signifikant, möglicherweise relevant", "Schätzwert über der MCID, KI schließt 0 ein. Studie zu klein."], ["Nicht signifikant und nicht relevant", "KI eng um 0. Ein echtes „wirkt nicht“."]]}, {"merk": "Achtung: Die MCID gilt für einzelne Patienten. Ein Gruppenunterschied von 1 Punkt kann bedeuten, dass ein Teil deutlich profitiert und ein Teil gar nicht. Schau, ob die Studie Responder-Anteile nennt."}]}, {"t": "6. Taugt das Messinstrument?", "b": [{"p": ["Eine Studie ist nur so gut wie ihre Messung. Drei Eigenschaften zählen."]}, {"tab": [["Reliabilität", "Kommt bei wiederholter Messung dasselbe heraus? Angegeben als [[ICC|icc]] oder Kappa."], ["Validität", "Misst das Instrument, was es messen soll? Der ODI misst Funktion bei Kreuzschmerz, nicht die Wirbelsäulenbeweglichkeit."], ["Änderungssensitivität", "Erkennt es Veränderung? Ein Fragebogen mit Deckeneffekt zeigt bei fitten Patienten keinen Fortschritt mehr."]]}, {"p": ["Patientenberichtete Endpunkte (Schmerz, Funktion, Lebensqualität) zählen für Patienten meist mehr als Ersatzwerte wie Muskeldicke im Ultraschall oder EMG-Aktivität. Solche [[Surrogatparameter|surrogat]] können sich bessern, ohne dass es dem Patienten besser geht."]}]}, {"t": "7. Warum es Patienten auch ohne Therapie besser geht", "b": [{"p": ["Viele Beschwerden in der Physiotherapie bessern sich von selbst. Wer ohne Kontrollgruppe nur vorher und nachher misst, schreibt diese Besserung der Therapie zu."]}, {"l": ["Natürlicher Verlauf: Akuter Kreuzschmerz bessert sich bei den meisten in den ersten Wochen deutlich.", "[[Regression zur Mitte|regression]]: Patienten kommen, wenn es am schlimmsten ist. Danach wird es statistisch fast immer besser.", "Placebo- und Kontexteffekte: Zuwendung, Erwartung, Berührung und ein gutes Gespräch wirken messbar.", "Hawthorne-Effekt: Wer beobachtet wird, verhält sich anders, übt etwa fleißiger."]}, {"merk": "Vorher-nachher ohne Kontrollgruppe zeigt nur, dass es besser wurde, nicht warum. Genau dafür braucht es die Kontrollgruppe."}]}], "info": {"asa": {"t": "ASA-Statement 2016", "x": ["Die American Statistical Association hat 2016 sechs Grundsätze zum p-Wert veröffentlicht.", "Kern: Der p-Wert zeigt, wie schlecht die Daten zu einem Modell passen. Er misst weder die Wahrscheinlichkeit der Hypothese noch die Größe des Effekts. Entscheidungen sollen nicht nur an einer Schwelle hängen, und Analysen gehören vollständig berichtet."], "q": "Wasserstein RL, Lazar NA. The American Statistician 2016"}, "alphabeta": {"t": "Fehler 1. und 2. Art", "x": ["Fehler 1. Art (Alpha): falsch positiv, meist auf 5 % begrenzt. Fehler 2. Art (Beta): falsch negativ, meist auf 20 % begrenzt, daraus folgt die Power von 80 %.", "Wer viele Endpunkte testet, sammelt Fehler 1. Art: Bei 20 Tests ist im Schnitt einer zufällig signifikant."]}, "cohen": {"t": "Cohens Faustregel", "x": ["Cohen schlug 1988 für standardisierte Effekte 0,2 klein, 0,5 mittel und 0,8 groß vor, ausdrücklich nur als Notbehelf.", "Ob ein Effekt klinisch zählt, hängt vom Thema ab. Besser: SMD in Punkte einer bekannten Skala zurückrechnen und mit der MCID vergleichen."], "q": "Cohen J. Statistical Power Analysis, 2. Aufl. 1988"}, "mcid": {"t": "MCID", "x": ["Minimal Clinically Important Difference: kleinste Veränderung, die Patienten als nützlich erleben (Jaeschke 1989).", "Sie hängt von Skala, Patientengruppe und Ausgangswert ab. Darum gibt es für dasselbe Instrument oft mehrere Werte. Nimm den, der zu deiner Patientengruppe passt."], "q": "Jaeschke R et al. Control Clin Trials 1989"}, "farrar": {"t": "Farrar 2001", "x": ["Auswertung von 10 Studien mit über 2.700 Schmerzpatienten auf der 11-stufigen Schmerzskala.", "Eine Senkung um etwa 2 Punkte oder 30 % entsprach dem, was Patienten als „viel besser“ einstuften."], "q": "Farrar JT et al. Pain 2001"}, "mdc": {"t": "MDC", "x": ["Minimal Detectable Change: kleinste Veränderung, die mit 95 % Sicherheit nicht nur Messfehler ist. Berechnet aus dem Standardmessfehler (SEM) und der Reliabilität.", "Bei Goniometrie am Knie liegt der MDC je nach Untersucher bei mehreren Grad. Eine Verbesserung um 3° kann also reiner Messfehler sein."]}, "icc": {"t": "ICC", "x": ["Intraklassen-Korrelationskoeffizient, Maß für die Übereinstimmung wiederholter Messungen von 0 bis 1.", "Grobe Einteilung nach Koo und Li: unter 0,5 schlecht, 0,5–0,75 mäßig, 0,75–0,9 gut, über 0,9 sehr gut."], "q": "Koo TK, Li MY. J Chiropr Med 2016"}, "surrogat": {"t": "Surrogatparameter", "x": ["Ersatzmessgröße, die leichter zu messen ist als das, was eigentlich zählt. Beispiele: Muskeldicke, EMG, Gelenkspalt im Röntgen, Laborwerte.", "Problem: Der Ersatzwert kann sich bessern, während Schmerz und Funktion gleich bleiben."]}, "regression": {"t": "Regression zur Mitte", "x": ["Extremwerte werden bei der nächsten Messung meist weniger extrem, rein statistisch.", "Wer an seinem schlechtesten Tag in die Praxis kommt, hat beim nächsten Termin mit hoher Wahrscheinlichkeit weniger Schmerz, auch ganz ohne Behandlung."]}}, "quellen": ["Wasserstein RL, Lazar NA. The ASA statement on p-values. Am Stat 2016", "Cohen J. Statistical Power Analysis for the Behavioral Sciences, 2. Aufl. 1988", "Jaeschke R, Singer J, Guyatt GH. Measurement of health status: ascertaining the minimal clinically important difference. Control Clin Trials 1989", "Farrar JT et al. Clinical importance of changes in chronic pain intensity. Pain 2001", "Koo TK, Li MY. Guideline of selecting and reporting ICC. J Chiropr Med 2016", "Higgins JPT et al. Cochrane Handbook, Kap. 6 und 15"], "fragen": [["Was gibt der p-Wert an?", ["Die Wahrscheinlichkeit, dass die Therapie wirkt", "Die Größe des Effekts", "Wie wahrscheinlich solche Daten wären, wenn es keinen Unterschied gäbe", "Den Anteil der Patienten, die profitieren"], 2, "Der p-Wert rechnet unter der Annahme der Nullhypothese. Er ist weder die Wahrscheinlichkeit der Hypothese noch ein Effektmaß."], ["Eine Studie findet keinen signifikanten Unterschied (p = 0,21). Was ist die richtige Schlussfolgerung?", ["Die Therapie wirkt sicher nicht", "Ein Effekt ist nicht nachgewiesen, er kann trotzdem existieren", "Die Therapie schadet", "Die Studie ist gefälscht"], 1, "Fehlender Nachweis ist kein Nachweis des Fehlens. Ein Blick aufs Konfidenzintervall zeigt, ob relevante Effekte noch drin sind."], ["Mittlere Differenz −0,8 Punkte NRS, 95-%-KI −1,9 bis +0,3. Was stimmt?", ["Nicht signifikant, weil das KI die 0 einschließt", "Signifikant, weil der Schätzwert negativ ist", "Signifikant, weil das KI schmal ist", "Nicht beurteilbar ohne p-Wert"], 0, "Bei Differenzen liegt die Nulllinie bei 0. Liegt sie im KI, ist das Ergebnis nicht signifikant."], ["Relatives Risiko 0,85, 95-%-KI 0,70 bis 1,05. Was folgt daraus?", ["Signifikante Senkung um 15 %", "Signifikante Erhöhung", "Nicht signifikant, weil das KI die 1 einschließt", "Das Risiko ist halbiert"], 2, "Bei Verhältnissen liegt die Nulllinie bei 1. Das KI reicht bis 1,05, also nicht signifikant."], ["Was zeigt ein breites Konfidenzintervall?", ["Einen großen Effekt", "Eine besonders gute Studie", "Eine hohe Power", "Eine unsichere, unpräzise Schätzung"], 3, "Breite heißt Unsicherheit, meist wegen kleiner Teilnehmerzahl oder großer Streuung."], ["Verletzungsrate ohne Programm 20 %, mit Programm 10 %. Wie hoch ist die NNT?", ["2", "5", "10", "50"], 2, "Absolute Risikoreduktion 10 Prozentpunkte, NNT = 1 / 0,10 = 10."], ["Warum klingt die relative Risikoreduktion oft beeindruckender als die absolute?", ["Weil sie falsch berechnet wird", "Weil sie immer über 50 % liegt", "Weil sie die Ausgangshäufigkeit ausblendet", "Weil sie nur in Cochrane-Reviews steht"], 2, "Von 2 % auf 1 % sind ebenfalls 50 % relativ, aber nur 1 Prozentpunkt absolut. Die NNT wäre 100."], ["Was beschreibt die MCID?", ["Die kleinste Veränderung, die Patienten als bedeutsam erleben", "Den kleinsten messbaren Unterschied über dem Messfehler", "Den Mittelwert der Kontrollgruppe", "Die Power einer Studie"], 0, "MCID = klinisch bedeutsam. Der kleinste Unterschied über dem Messfehler ist der MDC."], ["Wie groß ist die MCID für Schmerz auf der 0-bis-10-Skala nach Farrar 2001 etwa?", ["0,5 Punkte", "5 Punkte", "50 %", "Etwa 2 Punkte oder 30 %"], 3, "Etwa 2 Punkte oder 30 % Reduktion entsprachen „viel besser“."], ["Eine Studie mit 3.000 Teilnehmern findet −0,4 Punkte Schmerz, p < 0,001. Wie bewertest du das?", ["Großer, wichtiger Effekt", "Nicht signifikant", "Statistisch signifikant, aber klinisch kaum relevant", "Die Studie ist zu klein"], 2, "Große Studien machen kleine Unterschiede signifikant. 0,4 Punkte liegen weit unter der MCID."], ["Wofür steht die Standardabweichung?", ["Die Unsicherheit des Mittelwerts", "Den Median", "Den Messfehler des Geräts", "Die Streuung der einzelnen Patienten um den Mittelwert"], 3, "SD = Streuung der Einzelwerte. Die Unsicherheit des Mittelwerts ist der Standardfehler."], ["Ein Patient hat bei der ersten Behandlung NRS 9, beim nächsten Termin NRS 6. Was solltest du mitbedenken?", ["Regression zur Mitte und natürlicher Verlauf", "Die Behandlung hat sicher gewirkt", "Der Patient übertreibt", "Die Skala ist ungültig"], 0, "Wer am schlimmsten Tag kommt, wird meist von selbst etwas besser. Deshalb braucht es in Studien eine Kontrollgruppe."], ["Was ist ein Surrogatparameter?", ["Ein patientenberichteter Endpunkt", "Eine Kontrollgruppe", "Ein Störfaktor", "Eine Ersatzmessgröße wie Muskeldicke statt Funktion"], 3, "Ersatzwerte sind leicht messbar, sagen aber nicht sicher, ob es dem Patienten besser geht."]]}, {"id": "stud-diag", "titel": "Tests bewerten: Sensitivität, Spezifität, Likelihood Ratio", "art": "grund", "block": "B", "min": 11, "bild": "fortbildung/bilder/studien/stud-lachman.webp", "abschnitte": [{"t": "1. Die Vierfeldertafel", "b": [{"p": ["Jeder klinische Test wird an einem Referenzstandard gemessen, etwa Arthroskopie oder MRT. Daraus ergeben sich vier Felder."]}, {"tab": [["Richtig positiv (a)", "Test positiv, Erkrankung da"], ["Falsch positiv (b)", "Test positiv, Erkrankung nicht da"], ["Falsch negativ (c)", "Test negativ, Erkrankung da"], ["Richtig negativ (d)", "Test negativ, Erkrankung nicht da"]]}, {"p": ["Alle Kennzahlen diagnostischer Studien werden aus diesen vier Feldern berechnet. Wer die Tafel einmal aufmalt, versteht den Rest von selbst."]}]}, {"t": "2. Sensitivität und Spezifität", "b": [{"tab": [["Sensitivität = a / (a + c)", "Anteil der Kranken, bei denen der Test positiv ist. Hoch = übersieht wenig."], ["Spezifität = d / (b + d)", "Anteil der Gesunden, bei denen der Test negativ ist. Hoch = schlägt selten falsch an."]]}, {"p": ["Daraus kommen zwei bekannte Merkhilfen. [[SnNout|snnout]]: Ist ein hochsensitiver Test negativ, kannst du die Erkrankung eher ausschließen. SpPin: Ist ein hochspezifischer Test positiv, kannst du sie eher bestätigen.", "Sensitivität und Spezifität stehen oft gegeneinander. Wer die Schwelle für „positiv“ senkt, findet mehr Kranke, erwischt aber auch mehr Gesunde."]}, {"merk": "Sensitiv zum Ausschließen, spezifisch zum Bestätigen."}]}, {"t": "3. Warum der positive Test oft weniger sagt, als man denkt", "b": [{"p": ["Für den Patienten vor dir zählt eine andere Frage: Wie wahrscheinlich ist er krank, wenn der Test positiv ist? Das ist der positive prädiktive Wert (PPV). Er hängt stark davon ab, wie häufig die Erkrankung in deiner Patientengruppe ist.", "Beispiel mit einem Test, der 90 % sensitiv und 90 % spezifisch ist, bei 1.000 Patienten:"]}, {"tab": [["Häufigkeit 10 % (100 krank)", "90 richtig positiv, 90 falsch positiv. PPV = 50 %. Jeder zweite Positive ist gesund."], ["Häufigkeit 50 % (500 krank)", "450 richtig positiv, 50 falsch positiv. PPV = 90 %."]]}, {"p": ["Derselbe Test ist in der Sportambulanz nach Kniedistorsion also viel aussagekräftiger als beim Screening von Menschen ohne Beschwerden."]}, {"merk": "Prädiktive Werte gelten nur für die Häufigkeit in der Studie. Für deine Praxis brauchst du Likelihood Ratios."}]}, {"t": "4. Likelihood Ratios: die nützlichste Zahl", "b": [{"p": ["Die Likelihood Ratio (LR) sagt, wie stark ein Testergebnis die Wahrscheinlichkeit verschiebt. Sie hängt nicht von der Häufigkeit ab und lässt sich deshalb auf deine Patienten übertragen."]}, {"tab": [["LR+ = Sensitivität / (1 − Spezifität)", "Wie stark ein positiver Test die Wahrscheinlichkeit erhöht"], ["LR− = (1 − Sensitivität) / Spezifität", "Wie stark ein negativer Test sie senkt"]]}, {"tab": [["LR+ über 10 oder LR− unter 0,1", "Große, oft entscheidende Verschiebung"], ["LR+ 5–10 oder LR− 0,1–0,2", "Mäßige Verschiebung"], ["LR+ 2–5 oder LR− 0,2–0,5", "Kleine, manchmal wichtige Verschiebung"], ["LR+ 1–2 oder LR− 0,5–1", "Kaum Verschiebung"]]}, {"p": ["Für den Kopf gibt es eine [[Faustregel|mcgee]]: LR 2 erhöht die Wahrscheinlichkeit um etwa 15 Prozentpunkte, LR 5 um etwa 30, LR 10 um etwa 45. Umgekehrt senken 0,5, 0,2 und 0,1 um etwa 15, 30 und 45 Prozentpunkte."]}, {"merk": "Schätz erst aus Anamnese und Befund, wie wahrscheinlich die Diagnose ist (Vortestwahrscheinlichkeit). Dann verschiebt der Test diese Zahl."}]}, {"t": "5. Beispiel: Lachman und Pivot Shift", "b": [{"p": ["Die bekannte [[Metaanalyse von Benjaminse|benjaminse]] fand für den Lachman-Test 85 % Sensitivität und 94 % Spezifität, für den Pivot Shift 24 % und 98 %."]}, {"tab": [["Lachman", "LR+ etwa 14, LR− etwa 0,16. Positiv bestätigt stark, negativ schließt mäßig gut aus."], ["Pivot Shift", "LR+ etwa 12, LR− etwa 0,78. Positiv bestätigt, negativ sagt fast nichts."]]}, {"p": ["Rechenweg Lachman: 0,85 / (1 − 0,94) = 0,85 / 0,06 ≈ 14. Und (1 − 0,85) / 0,94 ≈ 0,16.", "Ein Patient mit Verdreh-Trauma, Knall und schneller Schwellung hat vielleicht 50 % Vortestwahrscheinlichkeit. Ein positiver Lachman hebt das nach der Faustregel auf über 90 %."]}, {"p": ["Eine neuere Metaanalyse mit strengerer Methode kam beim Lachman nur auf 81 % und 85 %. Auch Metaanalysen hängen also von Auswahl und Rechenmodell ab."]}, {"merk": "Ein negativer Pivot Shift entlastet nicht. Für den Ausschluss taugt er nicht, für die Bestätigung schon."}]}, {"t": "6. Woran du gute Diagnosestudien erkennst", "b": [{"p": ["Diagnosestudien werden mit [[QUADAS-2|quadas]] bewertet und nach STARD berichtet. Die häufigsten Fehler überschätzen den Test:"]}, {"l": ["Spektrum-Bias: Nur eindeutig Kranke und völlig Gesunde werden verglichen. Im Praxisalltag sind die unklaren Fälle die Regel, dort schneidet der Test schlechter ab.", "Verifikations-Bias: Nur wer im Test positiv war, bekommt den Referenzstandard (etwa die Arthroskopie).", "Fehlende Verblindung: Wer den Test macht, kennt schon das MRT.", "Schwacher Referenzstandard: Wird gegen einen ungenauen Standard geprüft, sind alle Zahlen unsicher.", "Untersuchung in Narkose: Pivot Shift und Lachman funktionieren in Narkose viel besser als im wachen, angespannten Patienten."]}, {"merk": "Kommt die Studie aus einer Klinik mit lauter klaren Fällen, sind ihre Zahlen für deine Praxis meist zu optimistisch."}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Einzelne Tests sind selten entscheidend. Tests in Kombination (Cluster) und die Anamnese bringen meist mehr.", "Zum Ausschließen Tests mit niedriger LR− nehmen, zum Bestätigen Tests mit hoher LR+.", "Ein Test mit LR nahe 1 verändert nichts. Den kannst du dir sparen oder nur zur Verlaufskontrolle nutzen.", "Achte auf die Zielgruppe der Studie. Sportler mit frischem Trauma sind nicht dasselbe wie 70-Jährige mit Gonarthrose.", "Wissen › Tests in Doku-Fix nennt die Werte je Test. Schau dort, ob LR oder nur Sensitivität und Spezifität angegeben sind."]}]}], "info": {"snnout": {"t": "SnNout und SpPin", "x": ["Sensitive test, Negative result, rule out. Specific test, Positive result, rule in.", "Die Merkhilfe stimmt nur grob. Ein Test mit 95 % Sensitivität, aber 30 % Spezifität hat eine LR− von etwa 0,17 und schließt weniger sicher aus, als die Sensitivität vermuten lässt. Rechne im Zweifel die LR."], "q": "Pewsner D et al. BMJ 2004"}, "mcgee": {"t": "Faustregel nach McGee", "x": ["McGee hat 2002 gezeigt, dass sich bei Vortestwahrscheinlichkeiten zwischen 10 und 90 % die Veränderung recht genau abschätzen lässt.", "LR 2, 5, 10 heißen etwa +15, +30, +45 Prozentpunkte. LR 0,5, 0,2, 0,1 heißen etwa −15, −30, −45 Prozentpunkte."], "q": "McGee S. J Gen Intern Med 2002"}, "benjaminse": {"t": "Benjaminse 2006", "x": ["Metaanalyse in JOSPT zu klinischen Tests bei VKB-Ruptur.", "Lachman 85 % sensitiv (KI 83–87) und 94 % spezifisch (KI 92–95). Pivot Shift 24 % und 98 %. Vordere Schublade nur bei chronischen Fällen gut (92 % und 91 %). Die Studien waren heterogen."], "q": "Benjaminse A et al. JOSPT 2006"}, "quadas": {"t": "QUADAS-2", "x": ["Werkzeug zur Bewertung diagnostischer Studien mit vier Bereichen: Patientenauswahl, Indextest, Referenzstandard sowie Ablauf und Zeitpunkte.", "Je Bereich wird das Verzerrungsrisiko und die Übertragbarkeit auf die eigene Fragestellung beurteilt."], "q": "Whiting PF et al. Ann Intern Med 2011"}}, "quellen": ["Jaeschke R, Guyatt GH, Sackett DL. Users' guides: diagnostic test. JAMA 1994", "McGee S. Simplifying likelihood ratios. J Gen Intern Med 2002", "Pewsner D et al. Ruling a diagnosis in or out with SpPIn and SnNOut. BMJ 2004", "Benjaminse A et al. Clinical diagnosis of an ACL rupture: a meta-analysis. JOSPT 2006", "Sokal PA et al. KSSTA 2022 (Lachman bivariat neu berechnet)", "Whiting PF et al. QUADAS-2. Ann Intern Med 2011", "Bossuyt PM et al. STARD 2015. BMJ 2015"], "fragen": [["Was beschreibt die Sensitivität?", ["Anteil der Kranken mit positivem Test", "Anteil der Gesunden mit negativem Test", "Wahrscheinlichkeit krank zu sein bei positivem Test", "Anteil aller richtigen Ergebnisse"], 0, "Sensitivität = richtig positiv / alle Kranken. Sie zeigt, wie wenig der Test übersieht."], ["Ein hochsensitiver Test ist negativ. Was folgt daraus?", ["Die Erkrankung ist eher bestätigt", "Die Erkrankung ist eher ausgeschlossen", "Nichts", "Der Test muss wiederholt werden"], 1, "SnNout: sensitiver Test, negatives Ergebnis, eher ausgeschlossen."], ["Wovon hängt der positive prädiktive Wert stark ab?", ["Von der Erfahrung des Untersuchers allein", "Von der Häufigkeit der Erkrankung in der Gruppe", "Von der Sensitivität allein", "Von der Studiengröße"], 1, "Bei seltener Erkrankung sind viele Positive falsch positiv. Der PPV sinkt mit der Häufigkeit."], ["Test mit 90 % Sensitivität und 90 % Spezifität, Häufigkeit 10 %. Wie hoch ist der PPV?", ["90 %", "50 %", "10 %", "81 %"], 1, "Von 1.000 Patienten: 90 richtig positiv, 90 falsch positiv. Also 50 %."], ["Wie berechnet man die positive Likelihood Ratio?", ["Sensitivität / (1 − Spezifität)", "Sensitivität / Spezifität", "(1 − Sensitivität) / Spezifität", "Spezifität / Sensitivität"], 0, "LR+ = Sensitivität / (1 − Spezifität)."], ["Ab welchem Wert gilt eine LR+ als große, oft entscheidende Verschiebung?", ["Über 1", "Über 10", "Über 2", "Über 100"], 1, "Nach Jaeschke: LR+ über 10 bzw. LR− unter 0,1 verschieben die Wahrscheinlichkeit stark."], ["Lachman nach Benjaminse: 85 % sensitiv, 94 % spezifisch. Wie hoch ist die LR+ etwa?", ["1,4", "5", "14", "85"], 2, "0,85 / 0,06 ≈ 14."], ["Der Pivot Shift ist bei deinem Patienten negativ. Was bedeutet das?", ["VKB-Ruptur ausgeschlossen", "VKB-Ruptur bestätigt", "Der Test war falsch ausgeführt", "Kaum Aussage, weil der Test wenig sensitiv ist"], 3, "Sensitivität nur 24 %, LR− etwa 0,78. Negativ sagt fast nichts, positiv bestätigt stark."], ["Vortestwahrscheinlichkeit 50 %, Testergebnis mit LR 5. Wo landest du etwa nach der Faustregel?", ["55 %", "65 %", "80 %", "99 %"], 2, "LR 5 erhöht um etwa 30 Prozentpunkte, also auf rund 80 %."], ["Was ist Spektrum-Bias?", ["Zu wenige Teilnehmer", "Der Untersucher kennt das MRT", "Nur eindeutig Kranke und eindeutig Gesunde werden verglichen", "Die Studie wurde nicht veröffentlicht"], 2, "Ohne die unklaren Fälle des Alltags sieht ein Test besser aus, als er ist."], ["Was ist Verifikations-Bias?", ["Nur Test-Positive bekommen den Referenzstandard", "Der Test wird zweimal gemacht", "Der Referenzstandard ist das MRT", "Die Patienten sind verblindet"], 0, "Bekommen nur Positive die Arthroskopie, fehlen die falsch Negativen. Die Sensitivität wird überschätzt."], ["Welche Struktur prüft der Therapeut auf diesem Bild?", ["Innenband", "Hinteres Kreuzband", "Vorderes Kreuzband", "Außenmeniskus"], 2, "Das ist der Lachman-Test: Knie leicht gebeugt, Tibia wird nach vorn gezogen, der Oberschenkel stabilisiert. Er prüft das vordere Kreuzband.", "fortbildung/bilder/studien/stud-lachman.webp"]]}, {"id": "stud-lesen", "titel": "Eine Studie lesen, Schritt für Schritt", "art": "anw", "block": "C", "min": 13, "bild": "fortbildung/bilder/studien/stud-lupe.webp", "abschnitte": [{"t": "1. Erst die Frage: PICO", "b": [{"p": ["Bevor du eine Studie liest, formuliere deine eigene Frage. Dann prüfst du, ob die Studie überhaupt dazu passt. Dafür gibt es das Schema [[PICO|pico]]."]}, {"tab": [["P – Patient", "Wer? z. B. Erwachsene mit Schulterschmerz seit über 3 Monaten"], ["I – Intervention", "Was? z. B. Krafttraining der Rotatorenmanschette, 12 Wochen"], ["C – Vergleich (Comparison)", "Wogegen? z. B. Kortisoninjektion, Sham, übliche Versorgung"], ["O – Ergebnis (Outcome)", "Was wird gemessen, wann? z. B. SPADI nach 12 Wochen und 1 Jahr"]]}, {"merk": "Passt das P der Studie nicht zu deinem Patienten, ist auch das beste Ergebnis für ihn nur eingeschränkt übertragbar."}]}, {"t": "2. Aufbau und die Abstract-Falle", "b": [{"p": ["Fast alle Studien folgen dem Aufbau Einleitung, Methoden, Ergebnisse, Diskussion. Viele lesen nur den Abstract. Das ist riskant: Autoren stellen ihre Ergebnisse oft schöner dar, als die Daten hergeben. Das nennt man [[Spin|spin]].", "In einer bekannten Auswertung von RCTs ohne signifikantes Hauptergebnis fand sich Spin in der Schlussfolgerung des Abstracts bei mehr als der Hälfte der Studien."]}, {"merk": "Der Abstract ist Werbung für die Studie. Entscheide nie nur nach dem Abstract."}]}, {"t": "3. Methoden: hier steht, ob man der Studie trauen kann", "b": [{"l": ["Teilnehmer: Ein- und Ausschlusskriterien, Rekrutierung, Setting. Ambulante Praxis oder Uniklinik? Freiwillige Studenten oder echte Patienten?", "Intervention: genau beschrieben? Dosis, Häufigkeit, Dauer, wer hat behandelt? Nur so kannst du es nachmachen ([[TIDieR|tidier]]).", "Kontrolle: Was bekam die Vergleichsgruppe? Ein schwacher Vergleich macht jede Therapie stark.", "Primärer Endpunkt: vorab festgelegt und im Studienregister eingetragen? Wann gemessen?", "Fallzahlplanung: Wurde vorher berechnet, wie viele Teilnehmer nötig sind?", "Randomisierung, verdeckte Zuteilung und Verblindung: beschrieben oder nur behauptet?"]}, {"merk": "Prüfe, ob der primäre Endpunkt in der Veröffentlichung derselbe ist wie im Register. Wechselt er, ist Vorsicht angesagt."}]}, {"t": "4. Ergebnisse: Flussdiagramm und Tabelle 1", "b": [{"p": ["Das Flussdiagramm zeigt, wie viele Patienten eingeschlossen, zugeteilt, behandelt und am Ende ausgewertet wurden. Schau, wie viele unterwegs verloren gingen und ob das in beiden Gruppen ähnlich war.", "Tabelle 1 beschreibt die Gruppen zu Beginn. Ähneln sie sich bei Alter, Schmerz, Dauer der Beschwerden? Größere Unterschiede trotz Randomisierung sind bei kleinen Studien möglich und können das Ergebnis verzerren."]}, {"tab": [["Intention-to-treat (ITT)", "Alle werden in der Gruppe ausgewertet, der sie zugeteilt wurden, auch Abbrecher. Bildet die Wirklichkeit ab und ist der Standard."], ["Per-Protocol", "Nur wer wie geplant behandelt wurde. Zeigt den Effekt bei Therapietreue, überschätzt ihn aber oft."]]}, {"p": ["Dann der primäre Endpunkt: Unterschied zwischen den Gruppen, mit Konfidenzintervall. Nicht die Veränderung innerhalb einer Gruppe. „Beide Gruppen verbesserten sich signifikant“ ist kein Beleg, dass die neue Therapie besser ist."]}, {"merk": "Entscheidend ist der Unterschied zwischen den Gruppen, nicht der Vorher-nachher-Effekt in einer Gruppe."}]}, {"t": "5. Den Forest Plot lesen", "b": [{"p": ["Metaanalysen zeigen ihre Ergebnisse fast immer als Forest Plot. Wer ihn einmal verstanden hat, liest einen Cochrane-Review in wenigen Minuten."]}, {"fig": [{"src": "fortbildung/bilder/studien/stud-forestplot.webp", "t": "Forest Plot, Beispiel", "c": "Fünf erfundene Studien zu Übungstherapie gegen Kontrolle beim Schmerz (NRS 0–10). Quadrate: Ergebnis je Studie, die Größe zeigt das Gewicht. Linien: 95-%-Konfidenzintervall. Raute: gepoolter Effekt. Senkrechte Linie bei 0: kein Unterschied. Eigene Grafik mit erfundenen Beispieldaten."}]}, {"l": ["Jede Zeile ist eine Studie. Das Quadrat ist ihr Schätzwert, die Linie ihr Konfidenzintervall.", "Größere Quadrate heißen mehr Gewicht, meist wegen mehr Teilnehmern.", "Die senkrechte Linie ist die Nulllinie (0 bei Differenzen, 1 bei Verhältnissen). Kreuzt eine Linie sie, ist diese Studie allein nicht signifikant.", "Die Raute unten ist das Gesamtergebnis. Ihre Mitte ist der gepoolte Effekt, ihre Breite das Konfidenzintervall.", "Achte auf die Beschriftung unter der Achse: Welche Seite spricht für die Therapie?"]}, {"p": ["Darunter steht meist die [[Heterogenität (I²)|i2]]. Sie zeigt, wie stark die Studien sich widersprechen. Bei hoher Heterogenität ist die Raute ein Durchschnitt aus sehr unterschiedlichen Ergebnissen und weniger verlässlich."]}, {"merk": "Raute komplett auf einer Seite der Nulllinie: signifikant. Dann prüfen, ob sie auch jenseits der MCID liegt."}]}, {"t": "6. Diskussion und Kleingedrucktes", "b": [{"l": ["Limitationen: Gute Autoren nennen sie selbst. Fehlen sie, ist das ein Warnzeichen.", "Finanzierung und Interessenkonflikte: Wer hat bezahlt? Hersteller des Geräts, Erfinder der Methode, Kursanbieter?", "Übertragbarkeit: Sind die Patienten und die Behandlung mit deiner Praxis vergleichbar? 24 Einzeltermine à 60 Minuten gibt es auf einem Kassenrezept nicht.", "Passt das Ergebnis zu anderen Studien? Eine einzelne überraschende Studie ist ein Hinweis, kein Beleg."]}]}, {"t": "7. Dein 15-Minuten-Plan", "b": [{"s": ["Titel und Abstract: Worum geht es, passt es zu meiner PICO-Frage?", "Methoden: Wer, was, wogegen, primärer Endpunkt, randomisiert und verblindet?", "Flussdiagramm: Wie viele sind abgesprungen?", "Tabelle 1: Waren die Gruppen am Anfang vergleichbar?", "Hauptergebnis: Unterschied zwischen den Gruppen mit Konfidenzintervall, verglichen mit der MCID.", "Nebenwirkungen: berichtet?", "Finanzierung und Interessenkonflikte.", "Eigenes Urteil in einem Satz: Was ändert das für meine Patienten?"]}, {"merk": "Kein Urteil ohne die Zahl mit Konfidenzintervall. „Signifikant besser“ allein reicht nicht."}]}], "info": {"pico": {"t": "PICO", "x": ["Schema, um eine klinische Frage so zu formulieren, dass man gezielt suchen und Studien prüfen kann.", "Erweiterungen: PICOT (mit Zeitraum) und PICOS (mit Studiendesign). Für die Suche: PubMed, PEDro, Cochrane Library."]}, "spin": {"t": "Spin", "x": ["Darstellung, die eine Behandlung besser wirken lässt, als die Ergebnisse hergeben, etwa durch Betonung von Nebenendpunkten oder Subgruppen.", "Boutron 2010 prüfte 72 RCTs mit nicht signifikantem Hauptergebnis: Spin im Titel bei 18 %, in der Schlussfolgerung des Abstracts bei 58 %."], "q": "Boutron I et al. JAMA 2010"}, "tidier": {"t": "TIDieR", "x": ["Checkliste mit 12 Punkten, wie Interventionen beschrieben werden sollen: was, warum, wer, wie, wo, wann und wie viel, Anpassungen, Therapietreue.", "Gerade bei Übungstherapie fehlen oft Dosis und Steigerung. Dann kannst du die Studie nicht nachmachen."], "q": "Hoffmann TC et al. BMJ 2014"}, "i2": {"t": "Heterogenität I²", "x": ["Anteil der Unterschiede zwischen Studien, der nicht durch Zufall erklärbar ist, in Prozent.", "Grobe Orientierung: etwa 25 % niedrig, 50 % mittel, 75 % hoch. Hohe Werte heißen: Studien messen vermutlich Verschiedenes, etwa andere Patienten oder Dosierungen."], "q": "Higgins JPT et al. BMJ 2003"}}, "quellen": ["Boutron I et al. Reporting and interpretation of RCTs with statistically nonsignificant results for primary outcomes. JAMA 2010", "Hopewell S et al. CONSORT 2025 statement. BMJ 2025", "Hoffmann TC et al. TIDieR checklist. BMJ 2014", "Higgins JPT et al. Measuring inconsistency in meta-analyses. BMJ 2003", "Higgins JPT et al. Cochrane Handbook, Kap. 10"], "fragen": [["Wofür steht das C in PICO?", ["Kosten", "Vergleich (Comparison)", "Konfidenz", "Kontrolle der Daten"], 1, "P Patient, I Intervention, C Comparison, O Outcome."], ["Warum reicht der Abstract für eine Entscheidung nicht?", ["Weil er zu kurz ist", "Weil er nie Zahlen enthält", "Weil Ergebnisse dort oft schöner dargestellt werden (Spin)", "Weil er von Lektoren geschrieben wird"], 2, "Spin ist häufig, besonders in der Schlussfolgerung des Abstracts."], ["Was ist bei einem Endpunkt verdächtig?", ["Er steht im Studienregister", "Er wird nach 12 Wochen gemessen", "Er wurde zwischen Register und Veröffentlichung gewechselt", "Er ist patientenberichtet"], 2, "Ein gewechselter primärer Endpunkt deutet auf selektive Berichterstattung hin."], ["Was zeigt Tabelle 1 in einem RCT?", ["Die Eigenschaften der Gruppen zu Beginn", "Das Hauptergebnis", "Die Nebenwirkungen", "Die Literaturliste"], 0, "Tabelle 1 zeigt, ob die Gruppen am Anfang vergleichbar waren."], ["Was bedeutet Intention-to-treat?", ["Nur Therapietreue werden ausgewertet", "Nur die Interventionsgruppe wird ausgewertet", "Alle werden in der zugeteilten Gruppe ausgewertet, auch Abbrecher", "Abbrecher werden durch Neue ersetzt"], 2, "ITT bildet die Wirklichkeit ab und erhält den Vorteil der Randomisierung."], ["„Beide Gruppen verbesserten sich signifikant.“ Was folgt daraus?", ["Noch nichts, entscheidend ist der Unterschied zwischen den Gruppen", "Die neue Therapie ist besser", "Beide Therapien sind gleich gut bewiesen", "Die Studie ist ungültig"], 0, "Verbesserung innerhalb einer Gruppe kann Verlauf, Regression oder Placebo sein. Zählen tut der Gruppenvergleich."], ["Was zeigt im Forest Plot die Größe eines Quadrats?", ["Den Effekt", "Das Jahr der Studie", "Das Gewicht der Studie", "Die Signifikanz"], 2, "Größere Quadrate stehen für mehr Gewicht, meist wegen mehr Teilnehmern und engerem KI."], ["Was ist im Forest Plot die Raute?", ["Die größte Studie", "Die Nulllinie", "Ein Ausreißer", "Das gepoolte Gesamtergebnis mit Konfidenzintervall"], 3, "Mitte der Raute = gepoolter Effekt, Breite = Konfidenzintervall."], ["Was zeigt ein I² von 80 %?", ["Sehr einheitliche Studien", "80 % der Patienten profitieren", "Hohe Heterogenität, die Studien widersprechen sich deutlich", "Signifikanz"], 2, "Ab etwa 75 % spricht man von hoher Heterogenität. Die Raute ist dann weniger verlässlich."], ["Wie viele der fünf Einzelstudien in diesem Forest Plot sind für sich allein signifikant?", ["Zwei", "Keine", "Vier", "Alle fünf"], 0, "Nur bei Studie B und Studie D liegt die ganze Linie links der Nulllinie. Die anderen drei kreuzen die 0. Zusammen ergibt sich trotzdem eine signifikante Raute.", "fortbildung/bilder/studien/stud-forestplot.webp"], ["Warum ist TIDieR für dich in der Praxis wichtig?", ["Es sorgt dafür, dass die Intervention so beschrieben ist, dass du sie nachmachen kannst", "Es bewertet die Statistik", "Es ersetzt die Ethikkommission", "Es misst Nebenwirkungen"], 0, "Ohne Dosis, Häufigkeit und Steigerung kannst du ein Übungsprogramm nicht übernehmen."]]}, {"id": "stud-bewerten", "titel": "Gut oder schlecht? Studien bewerten", "art": "anw", "block": "C", "min": 14, "bild": "fortbildung/bilder/studien/stud-checkliste.webp", "abschnitte": [{"t": "1. Zwei Fragen: stimmt es, und gilt es für mich?", "b": [{"p": ["Gute Studienbewertung fragt zweimal. Die innere Validität fragt, ob das Ergebnis stimmt, also ob die Studie frei von Verzerrung ist. Die äußere Validität fragt, ob es sich auf deine Patienten übertragen lässt.", "Eine Studie kann methodisch perfekt sein und trotzdem nichts für deine Praxis sagen, etwa weil nur junge Sportler mit 30 Einzelterminen behandelt wurden."]}, {"merk": "Erst prüfen, ob das Ergebnis stimmt. Dann prüfen, ob es zu deinem Patienten passt."}]}, {"t": "2. Die wichtigsten Verzerrungen (Bias)", "b": [{"tab": [["Selektion", "Gruppen unterscheiden sich schon am Anfang. Schutz: echte Randomisierung und verdeckte Zuteilung."], ["Durchführung (Performance)", "Eine Gruppe bekommt mehr Zuwendung oder Zusatzbehandlung. Schutz: Verblindung von Patient und Therapeut, gleiche Kontaktzeit."], ["Messung (Detection)", "Der Untersucher weiß, wer was bekam, und misst anders. Schutz: verblindeter Untersucher."], ["Ausfall (Attrition)", "Viele brechen ab, oft gerade die, denen es schlecht geht. Schutz: geringe Ausfallquote, ITT-Analyse."], ["Berichterstattung (Reporting)", "Nur die schönen Endpunkte werden berichtet. Schutz: Studienregister und veröffentlichtes Protokoll."], ["Publikation", "Studien ohne Effekt erscheinen seltener. Darum wirkt die Literatur insgesamt zu positiv."]]}, {"merk": "Die meisten Verzerrungen machen die Therapie besser, als sie ist. Unsauber gemachte Studien finden öfter Effekte."}]}, {"t": "3. Die PEDro-Skala", "b": [{"p": ["Für Physiotherapie-Studien ist die [[PEDro-Skala|pedro]] das bekannteste Werkzeug. Jede Studie in der PEDro-Datenbank hat einen Wert. Sie hat 11 Punkte, der erste (Einschlusskriterien) zählt nicht mit. So entsteht ein Wert von 0 bis 10."]}, {"l": ["2 Zufällige Zuteilung", "3 Verdeckte Zuteilung", "4 Gruppen zu Beginn vergleichbar", "5 Patienten verblindet", "6 Therapeuten verblindet", "7 Untersucher verblindet", "8 Mindestens 85 % der Teilnehmer für einen Hauptendpunkt ausgewertet", "9 Intention-to-treat-Analyse", "10 Statistischer Vergleich zwischen den Gruppen", "11 Punktschätzer und Streuungsmaß angegeben"]}, {"tab": [["9–10", "Exzellent"], ["6–8", "Gut"], ["4–5", "Mäßig"], ["unter 4", "Schwach"]]}, {"p": ["Bei Übungs- und Manualtherapie lassen sich Patient und Therapeut meist nicht verblinden. Realistisch ist dort oft 8 von 10 das Maximum. Ein PEDro-Wert sagt außerdem nur etwas über die Methodik, nicht darüber, ob die Therapie wirkt oder ob der Effekt groß ist."]}, {"merk": "PEDro 6 oder mehr ist für Physio-Studien ordentlich. Aber die Zahl ersetzt nicht den Blick auf Kontrolle, Endpunkt und Effektgröße."}]}, {"t": "4. RoB 2: das Cochrane-Werkzeug", "b": [{"p": ["Cochrane-Reviews nutzen [[RoB 2|rob2]]. Es bewertet nicht die ganze Studie, sondern ein bestimmtes Ergebnis, und zwar in fünf Bereichen."]}, {"tab": [["1 Randomisierung", "Echte Zufallsfolge, verdeckt, Gruppen vergleichbar?"], ["2 Abweichung von der geplanten Behandlung", "Wussten Beteiligte, wer was bekam, und hat das die Behandlung verändert?"], ["3 Fehlende Daten", "Fehlen Ergebnisse, und kann das das Resultat verzerren?"], ["4 Messung des Endpunkts", "Wusste der Messende Bescheid, und war die Messung geeignet?"], ["5 Auswahl des berichteten Ergebnisses", "Wurde vorab festgelegt, was berichtet wird?"]]}, {"p": ["Für jeden Bereich gibt es „niedriges Risiko“, „einige Bedenken“ oder „hohes Risiko“. In Reviews siehst du das oft als Ampel aus grünen, gelben und roten Punkten neben dem Forest Plot."]}]}, {"t": "5. GRADE: wie sicher ist die Gesamtaussage?", "b": [{"p": ["PEDro und RoB 2 bewerten einzelne Studien. [[GRADE|grade5]] bewertet den ganzen Studienbefund zu einer Frage und einem Endpunkt. Ergebnisse aus RCTs starten bei „hoch“, aus Beobachtungsstudien bei „niedrig“. Dann wird abgewertet oder seltener aufgewertet."]}, {"tab": [["Abwerten", "Verzerrungsrisiko, Inkonsistenz (Studien widersprechen sich), Indirektheit (andere Patienten oder Vergleiche als gefragt), Ungenauigkeit (breites KI, wenige Patienten), Publikationsbias"], ["Aufwerten (selten)", "Sehr großer Effekt, Dosis-Wirkungs-Beziehung, Störfaktoren würden den Effekt eher verkleinern"]]}, {"tab": [["Hoch", "Der wahre Effekt liegt sehr wahrscheinlich nahe am geschätzten."], ["Moderat", "Wahrscheinlich nahe dran, könnte aber deutlich abweichen."], ["Niedrig", "Der wahre Effekt kann deutlich anders sein."], ["Sehr niedrig", "Der wahre Effekt ist wahrscheinlich deutlich anders."]]}, {"p": ["In der Physiotherapie sind „niedrig“ und „sehr niedrig“ leider häufig. Das heißt nicht, dass eine Therapie nicht wirkt, sondern dass wir es nicht sicher wissen und neue Studien das Bild noch verändern können."]}, {"merk": "Sehr niedrige Vertrauenswürdigkeit heißt: Neue Studien können das Ergebnis jederzeit umdrehen. Entsprechend vorsichtig formulieren."}]}, {"t": "6. Warnsignale", "b": [{"l": ["Keine Kontrollgruppe, nur vorher und nachher gemessen.", "Kein Eintrag im Studienregister, kein Protokoll.", "Kleine Studie mit riesigem Effekt. Echte Effekte in der Physiotherapie sind meist klein bis mittel.", "Viele Endpunkte, nur die signifikanten werden betont.", "Subgruppen-Ergebnisse als Hauptbotschaft („bei Frauen über 50 wirkte es“), ohne dass das vorher geplant war.", "Nur Surrogatparameter wie EMG oder Muskeldicke statt Schmerz und Funktion.", "Mehr als 15 % Ausfälle oder deutlich ungleiche Ausfälle zwischen den Gruppen.", "Finanziert vom Hersteller oder vom Erfinder der Methode, ohne unabhängige Bestätigung.", "Veröffentlicht in einer [[Raubzeitschrift|predatory]]."]}, {"merk": "Je besser ein Ergebnis klingt und je kleiner die Studie, desto skeptischer solltest du werden."}]}, {"t": "7. Dein Urteil in acht Fragen", "b": [{"s": ["Passt die Frage (PICO) zu meinem Patienten?", "Randomisiert mit verdeckter Zuteilung?", "Untersucher verblindet?", "Ausfälle unter 15 % und ITT-Analyse?", "Primärer Endpunkt vorab registriert und unverändert?", "Sinnvolle Kontrollgruppe (nicht nur Warteliste)?", "Effekt mit Konfidenzintervall, verglichen mit der MCID?", "Bestätigen andere Studien das Ergebnis, und wie bewertet GRADE die Gesamtlage?"]}, {"p": ["Fünf oder mehr klare Ja-Antworten: Die Studie kann deine Praxis begründen. Drei oder weniger: Sieh sie als Hinweis, nicht als Beleg."]}, {"merk": "Eine gute Studie ist kein Freibrief. Erst mehrere übereinstimmende gute Studien machen aus einem Ergebnis eine Empfehlung."}]}], "info": {"pedro": {"t": "PEDro", "x": ["Physiotherapy Evidence Database, kostenlos unter pedro.org.au. Enthält Physiotherapie-RCTs, Reviews und Leitlinien, RCTs mit Bewertung.", "Die Einteilung 9–10 exzellent, 6–8 gut, 4–5 mäßig, unter 4 schwach stammt aus der Fachliteratur, nicht von PEDro selbst. Die Übereinstimmung zwischen Bewertern ist für den Gesamtwert mäßig bis gut."], "q": "Cashin AG, McAuley JH. J Physiother 2020"}, "rob2": {"t": "RoB 2", "x": ["Version 2 des Cochrane-Werkzeugs für Verzerrungsrisiko in randomisierten Studien, veröffentlicht 2019.", "Für jeden Bereich gibt es Leitfragen. Das Gesamturteil richtet sich nach dem schlechtesten Bereich: Ein „hohes Risiko“ irgendwo macht das Ergebnis insgesamt hochriskant."], "q": "Sterne JAC et al. BMJ 2019"}, "grade5": {"t": "GRADE im Review", "x": ["In Cochrane-Reviews steht GRADE in der Tabelle „Summary of findings“. Dort siehst du je Endpunkt Effekt, Konfidenzintervall, Teilnehmerzahl und die Vertrauenswürdigkeit mit Begründung.", "Diese Tabelle ist oft der schnellste Weg zum Kern eines Reviews."], "q": "Cochrane Handbook, Kap. 14"}, "predatory": {"t": "Raubzeitschriften", "x": ["Zeitschriften, die gegen Gebühr fast alles veröffentlichen, ohne echte Begutachtung durch Fachleute.", "Hinweise: aggressive E-Mail-Werbung, Annahme in wenigen Tagen, kein Eintrag in PubMed/MEDLINE, unklare Herausgeber. Im Zweifel prüfen, ob die Zeitschrift im DOAJ oder in MEDLINE gelistet ist."]}}, "quellen": ["Cashin AG, McAuley JH. Clinimetrics: PEDro Scale. J Physiother 2020", "Maher CG et al. Reliability of the PEDro scale. Phys Ther 2003", "Sterne JAC et al. RoB 2: a revised tool for assessing risk of bias in randomised trials. BMJ 2019", "Schünemann HJ et al. Cochrane Handbook, Kap. 14 (GRADE)", "Guyatt GH et al. GRADE guidelines series. J Clin Epidemiol 2011", "Boutron I et al. JAMA 2010"], "fragen": [["Was fragt die innere Validität?", ["Ob das Ergebnis auf meine Patienten passt", "Ob die Studie gut geschrieben ist", "Ob sie in Deutschland stattfand", "Ob das Ergebnis frei von Verzerrung stimmt"], 3, "Innere Validität = stimmt es? Äußere Validität = gilt es für meine Patienten?"], ["Der Untersucher wusste, wer behandelt wurde, und misst die Beweglichkeit. Welcher Bias droht?", ["Selektionsbias", "Messbias (Detection)", "Publikationsbias", "Ausfallbias"], 1, "Wer weiß, was der Patient bekam, misst unbewusst anders. Schutz: verblindeter Untersucher."], ["Warum ist eine hohe Abbrecherquote problematisch?", ["Weil die Studie dann länger dauert", "Weil sie die Power erhöht", "Weil oft gerade die abbrechen, denen es schlecht geht", "Weil PEDro dann nicht anwendbar ist"], 2, "Wer abspringt, ist selten zufällig verteilt. Das verzerrt das Ergebnis meist zugunsten der Therapie."], ["Wie viele Punkte kann man auf der PEDro-Skala maximal erreichen?", ["11", "10", "12", "100"], 1, "11 Kriterien, der erste zählt nicht mit. Also 0 bis 10."], ["Eine Studie hat PEDro 7. Wie wird das üblicherweise eingestuft?", ["Exzellent", "Gut", "Mäßig", "Schwach"], 1, "6 bis 8 gilt als gut, 9 bis 10 als exzellent."], ["Warum erreichen Übungsstudien selten 10 PEDro-Punkte?", ["Weil sie schlecht gemacht sind", "Weil Patient und Therapeut sich kaum verblinden lassen", "Weil sie nie randomisiert werden", "Weil PEDro nur Medikamente bewertet"], 1, "Die Punkte für verblindete Patienten und Therapeuten sind bei aktiver Therapie kaum erreichbar."], ["Was bewertet RoB 2?", ["Eine ganze Leitlinie", "Die Vertrauenswürdigkeit eines ganzen Studienbefunds", "Das Verzerrungsrisiko eines Ergebnisses einer randomisierten Studie", "Die Qualität einer Diagnosestudie"], 2, "RoB 2 schaut auf ein bestimmtes Ergebnis in fünf Bereichen. Den ganzen Befund bewertet GRADE, Diagnosestudien QUADAS-2."], ["Wo startet GRADE bei Ergebnissen aus RCTs?", ["Bei sehr niedrig", "Bei niedrig", "Bei moderat", "Bei hoch"], 3, "RCTs starten hoch, Beobachtungsstudien niedrig. Dann wird abgewertet."], ["Welcher Grund führt bei GRADE zur Abwertung?", ["Großer Effekt", "Dosis-Wirkungs-Beziehung", "Viele Teilnehmer", "Ungenauigkeit durch breites Konfidenzintervall"], 3, "Abwertung: Verzerrung, Inkonsistenz, Indirektheit, Ungenauigkeit, Publikationsbias."], ["Was bedeutet „sehr niedrige Vertrauenswürdigkeit“?", ["Der wahre Effekt ist wahrscheinlich deutlich anders als geschätzt", "Die Therapie wirkt nicht", "Die Studien sind gefälscht", "Die Therapie ist gefährlich"], 0, "Wir wissen es nicht sicher. Neue Studien können das Ergebnis deutlich verändern."], ["Eine Pilotstudie mit 18 Patienten berichtet einen riesigen Effekt. Wie gehst du damit um?", ["Sofort übernehmen", "Ignorieren, weil Pilotstudien verboten sind", "Nur bei Privatpatienten anwenden", "Skeptisch bleiben, kleine Studien überschätzen Effekte oft"], 3, "Kleine Studien mit großen Effekten schrumpfen in größeren Studien meist deutlich."], ["Was ist ein Warnsignal bei Subgruppen?", ["Sie waren vorab geplant", "Es gibt keine Subgruppen", "Ein nicht geplantes Subgruppenergebnis wird zur Hauptbotschaft", "Die Subgruppe ist groß"], 2, "Ungeplante Subgruppen sind Zufallsfunde. Bei genug Untergruppen ist immer eine signifikant."]]}, {"id": "stud-pruefung", "titel": "Prüfung: eine Studie im Schnellcheck", "art": "pruef", "block": "D", "min": 9, "bild": "fortbildung/bilder/studien/stud-pyramide.webp", "abschnitte": [{"t": "Der Fall", "b": [{"p": ["Ein Patient bringt dir einen Artikel mit. Er will unbedingt Stoßwelle für seine Ferse. Hier ist die Zusammenfassung der Studie. Sie ist erfunden, enthält aber typische Schwächen echter Studien. Lies sie in Ruhe und beantworte dann die Fragen. Ob Stoßwelle bei Fersenschmerz wirkt, ist hier nicht die Frage. Es geht nur darum, was diese eine Studie zeigen kann."]}, {"l": ["Titel: Radiale Stoßwelle bei Fersenschmerz – eine randomisierte Studie (erfundenes Übungsbeispiel)", "Hintergrund: Stoßwelle wird bei Fersenschmerz (Plantarfasziopathie) oft eingesetzt.", "Methoden: 40 Patienten aus einer Privatpraxis wurden nach Geburtsmonat (gerade/ungerade) in zwei Gruppen eingeteilt. Gruppe A bekam 3 Sitzungen Stoßwelle plus Dehnprogramm, Gruppe B kam auf die Warteliste. Der Therapeut, der behandelte, maß auch den Schmerz (NRS 0–10). Gemessen wurde nach 6 Wochen. Die Studie wurde vom Gerätehersteller finanziert. Kein Registereintrag.", "Ergebnisse: 31 von 40 Patienten wurden ausgewertet (A: 18 von 20, B: 13 von 20). Schmerz in Gruppe A von 7,1 auf 3,4 gesenkt (p < 0,001). Unterschied zwischen den Gruppen −1,1 Punkte (95-%-KI −2,6 bis +0,4). Morgendlicher Anlaufschmerz, Gehstrecke und Schlafqualität besserten sich in Gruppe A signifikant, bei Frauen über 50 auch die Lebensqualität.", "Schlussfolgerung: Radiale Stoßwelle ist hochwirksam bei Fersenschmerz und sollte routinemäßig angeboten werden."]}, {"merk": "Geh in Gedanken die acht Fragen aus „Gut oder schlecht?“ durch, bevor du ins Quiz startest."}]}], "quellen": ["Erfundenes Übungsbeispiel, keine echte Studie", "Inhalte aus den Einheiten 1–5 dieses Lernpfads"], "fragen": [["Die Patienten wurden nach geradem oder ungeradem Geburtsmonat eingeteilt. Ist das eine echte Randomisierung?", ["Ja, das ist Zufall", "Ja, wenn beide Gruppen gleich groß sind", "Nur bei mehr als 100 Patienten", "Nein, die Zuteilung ist vorhersehbar und nicht verdeckt"], 3, "Wer den Geburtsmonat kennt, kennt die Gruppe. Das ist Quasi-Randomisierung ohne verdeckte Zuteilung."], ["Welche Kontrollgruppe hat die Studie?", ["Warteliste", "Sham-Stoßwelle", "Dehnprogramm allein", "Einlagen"], 0, "Gegen Warteliste sieht fast jede Behandlung gut aus, weil Zuwendung und Erwartung fehlen."], ["Gruppe A bekam Stoßwelle plus Dehnprogramm. Was ist das Problem?", ["Keins", "Dehnen ist verboten", "Zu wenige Sitzungen", "Man kann den Effekt nicht der Stoßwelle allein zuschreiben"], 3, "Zwei Behandlungen gegen nichts: Was gewirkt hat, bleibt offen."], ["Der behandelnde Therapeut maß auch den Schmerz. Welche Verzerrung droht?", ["Publikationsbias", "Selektionsbias", "Keine", "Messbias durch fehlende Untersucher-Verblindung"], 3, "Wer behandelt und misst, weiß, wer was bekam. Der Untersucher war nicht verblindet."], ["Wie viele Patienten fehlen in der Kontrollgruppe?", ["0", "2", "7", "9"], 2, "B: 13 von 20 ausgewertet, also 7 fehlen (35 %). Dazu ungleich verteilt gegenüber 2 in Gruppe A."], ["Was sagt „Schmerz in Gruppe A von 7,1 auf 3,4 gesenkt, p < 0,001“?", ["Nur, dass es Gruppe A besser ging. Das kann Verlauf, Regression oder Placebo sein", "Stoßwelle wirkt sicher", "Dass der Unterschied zwischen den Gruppen groß ist", "Dass die Studie gut ist"], 0, "Ein Vorher-nachher-Effekt in einer Gruppe ist kein Gruppenvergleich."], ["Unterschied zwischen den Gruppen −1,1 Punkte, 95-%-KI −2,6 bis +0,4. Ist das signifikant?", ["Nein, das KI schließt die 0 ein", "Ja", "Ja, weil −1,1 negativ ist", "Kann man nicht sagen"], 0, "Die Nulllinie 0 liegt im Intervall. Der eigentliche Vergleich ist also nicht signifikant."], ["Liegt der Schätzwert von −1,1 Punkten über der MCID von etwa 2 Punkten?", ["Ja, deutlich", "Genau auf der MCID", "Nein, er liegt darunter", "Die MCID gilt hier nicht"], 2, "1,1 ist weniger als 2. Selbst der Schätzwert wäre klinisch kaum relevant."], ["Mehrere Nebenendpunkte und „Frauen über 50“ werden betont. Was ist das?", ["Typischer Spin mit ungeplanter Subgruppe", "Gute Praxis", "Pflicht nach CONSORT", "Ein Zeichen für hohe Power"], 0, "Nicht signifikantes Hauptergebnis, dafür Nebenendpunkte und Subgruppe im Vordergrund: klassischer Spin."], ["Was fehlt völlig und hätte selektive Berichterstattung erschwert?", ["Ein Literaturverzeichnis", "Die Ethik der Autoren", "Der Eintrag im Studienregister", "Ein Foto des Geräts"], 2, "Ohne Registereintrag kann niemand prüfen, ob der Hauptendpunkt vorab festgelegt war."], ["Wie ordnest du die Finanzierung durch den Gerätehersteller ein?", ["Unwichtig", "Als Beweis für Betrug", "Als Qualitätsmerkmal", "Als möglichen Interessenkonflikt, der Vorsicht verlangt"], 3, "Herstellerfinanzierung macht eine Studie nicht falsch, ist aber mit positiveren Ergebnissen verbunden. Unabhängige Bestätigung fehlt."], ["Wie viele PEDro-Punkte bekäme diese Studie ungefähr?", ["9–10", "6–8", "2–4", "Gar nicht bewertbar"], 2, "Keine echte Randomisierung, nicht verdeckt, keine Verblindung, Ausfall über 15 %, keine ITT. Übrig bleiben etwa Gruppenvergleich, Punktschätzer und eventuell vergleichbare Gruppen."], ["Passt die Schlussfolgerung „hochwirksam, routinemäßig anbieten“ zu den Daten?", ["Ja", "Nein, der Gruppenunterschied ist nicht signifikant und unter der MCID", "Ja, für Frauen über 50", "Ja, weil p < 0,001"], 1, "Die Schlussfolgerung stützt sich auf Vorher-nachher und Nebenbefunde. Das Hauptergebnis gibt das nicht her."], ["Wie würde GRADE die Aussage nur aus dieser einen Studie etwa einstufen?", ["Hoch", "Moderat", "Sehr niedrig", "GRADE gilt nur für Medikamente"], 2, "Hohes Verzerrungsrisiko, Ungenauigkeit (kleine Zahl, breites KI), keine Bestätigung. Das endet bei sehr niedrig."], ["Was sagst du dem Patienten am ehrlichsten?", ["„Die Studie beweist, dass es wirkt.“", "„Studien sind alle gekauft.“", "„Diese Studie zeigt das leider nicht sicher. Lass uns anschauen, was in Leitlinien und besseren Studien steht.“", "„Stoßwelle ist gefährlich.“"], 2, "Ehrlich, ohne Abwertung des Patienten, und mit Blick auf die gesamte Studienlage statt einer einzelnen Studie."]]}]});
